<template>
  <div id="component">
    <canvas class="paintable-canvas" ref="paintableCanvas"></canvas>
    <div class="text-left">
      <label>Pen thickness:</label>
      <v-slider
        v-model="lineWidth"
        hide-details
        :min="25"
        :max="60"
        thumb-label
      ></v-slider>
    </div>
  </div>
</template>

<script>
import { useDrawingStore } from '@/stores/drawing'
import { mapStores, mapWritableState } from 'pinia'

export default {
  name: 'DrawingCanvas',
  data: () => ({
    canvas: null,
    context: null,
    coord: { x: 0, y: 0 }
  }),
  mounted: function () {
    this.canvas = this.$refs.paintableCanvas
    this.context = this.canvas.getContext('2d')

    document.addEventListener('mousedown', (event) => {
      document.addEventListener('mousemove', this.draw)
      this.reposition(event)
    })

    document.addEventListener('mouseup', (event) => {
      document.removeEventListener('mousemove', this.draw)
    })

    this.canvas.addEventListener('touchstart', (event) => {
      this.reposition(event)
      document.addEventListener('mousemove', this.draw)
    })

    this.canvas.addEventListener('touchend', (event) => {
      document.removeEventListener('mousemove', this.draw)
    })

    this.canvas.addEventListener('touchmove', (e) => {
      e.preventDefault()
      const touch = e.touches[0]
      const mouseEvent = new MouseEvent('mousemove', {
        clientX: touch.clientX,
        clientY: touch.clientY
      })
      document.dispatchEvent(mouseEvent)
    }, false)

    window.addEventListener('resize', this.resize)

    setTimeout(() => {
      this.resize()
      this.context.fillStyle = 'white'
      this.context.fillRect(0, 0, this.canvas.width, this.canvas.height)
    }, 200)
  },
  computed: {
    ...mapStores(useDrawingStore),
    ...mapWritableState(useDrawingStore, ['images', 'lineWidth'])
  },
  methods: {
    draw: function (event) {
      this.context.beginPath()
      this.context.lineWidth = this.lineWidth
      this.context.lineCap = 'round'
      this.context.strokeStyle = '#000000'
      this.context.moveTo(this.coord.x, this.coord.y)
      this.reposition(event)
      this.context.lineTo(this.coord.x, this.coord.y)
      this.context.stroke()
    },
    reposition: function (event) {
      this.coord.x = event.clientX - this.canvas.getBoundingClientRect().x
      this.coord.y = event.clientY - this.canvas.getBoundingClientRect().y
    },
    resize: function (event) {
      this.canvas.width = this.canvas.clientWidth
      this.canvas.height = this.canvas.clientHeight
    },
    clear: function () {
      this.context.clearRect(0, 0, this.canvas.width, this.canvas.height)
      this.context.fillStyle = 'white'
      this.context.fillRect(0, 0, this.canvas.width, this.canvas.height)
    },
    classifyImage: function () {
      const OUTPUT_SIZE = 128
      const newCanvas = document.createElement('canvas')
      newCanvas.width = OUTPUT_SIZE
      newCanvas.height = OUTPUT_SIZE
      newCanvas.getContext('2d').drawImage(this.canvas, 0, 0, OUTPUT_SIZE, OUTPUT_SIZE)

      // Add image
      this.drawingStore.classifyImage(newCanvas)

      // Clear canvas
      this.clear()
      // Convert to Blob and upload to Azure store

      // document.getElementById('component').appendChild(newCanvas)
      // window.location.href = newCanvas.toDataURL().replace('image/png', 'image/octet-stream')
    }
  }
}

</script>

<style>
    .paintable-canvas {
        border: 1px solid #000;
        aspect-ratio: 1 / 1;
        width: 100%;
        max-width: 500px;
        -moz-box-shadow: 0 0 10px #CCC;
        -webkit-box-shadow: 0 0 10px #CCC;
        box-shadow: 0 0 10px #CCC;
    }
</style>
